struct Configuration {
    int mode;
    float timeout;
    const char *name;
};

// Positional initialization: Strict declaration order (mode, timeout, name)
struct Configuration cfg_a = { 1, 15.0f, "Default" };

// Designated initializers (C99+): Arbitrary order allowed
// Uninitialized members are set to zero/NULL
struct Configuration cfg_b = {
    .name = "Logging",
    .timeout = 5.0f
    // .mode defaults to 0
};

// Mixing: Positional values must precede subsequent designators
struct Configuration cfg_c = { 
    1,          // Positional: cfg_c.mode = 1
    .name = "Test", 
    2.5f        // ERROR: Cannot follow a designator 
};
